interface SeaAnimal {
    void swim();
    default void communicate() {
        System.out.println("Sea animals communicate.");
    }
}

class Shark implements SeaAnimal {
    public void swim() { System.out.println("Shark swims."); }
    @Override
    public void communicate() { System.out.println("Shark communicates in its own way."); }
}

class Dolphin implements SeaAnimal {
    public void swim() { System.out.println("Dolphin swims."); }
}

class Main {
    public static void main(String[] args) {
        SeaAnimal shark = new Shark(), dolphin = new Dolphin();
        shark.swim();
        shark.communicate();
        dolphin.swim();
        dolphin.communicate();
    }
}

interface Student {
    default void personalLife() {
        dailyRoutine();
        System.out.println("Personal life activities.");
    }
    default void professionalLife() {
        dailyRoutine();
        System.out.println("Professional life activities.");
    }
    private void dailyRoutine() {
        System.out.println("Student wakes up and checks the mobile.");
    }
}
class Learner implements Student { }
class Main {
    public static void main(String[] args) {
        Student student = new Learner();
        student.personalLife();
        student.professionalLife();
    }
}

interface InterfaceUtility {
    static void firstOperation() {
        commonLogic();
        System.out.println("First static operation completed.");
    }
    static void secondOperation() {
        commonLogic();
        System.out.println("Second static operation completed.");
    }
    private static void commonLogic() {
        System.out.println("Common interface logic.");
    }
}
class Main {
    public static void main(String[] args) {
        InterfaceUtility.firstOperation();
        InterfaceUtility.secondOperation();
    }
}

